from typing import List

class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        prefix = []
        total_skill = 0
        for s in skill:
            total_skill += s
            prefix.append(total_skill)

        start = 0
        for j in range(1, len(mana)):
            prev_mana = mana[j - 1]
            cur_mana = mana[j]
            best_gap = 0
            prev_prefix = 0

            for p in prefix:
                gap = p * prev_mana - prev_prefix * cur_mana
                if gap > best_gap:
                    best_gap = gap
                prev_prefix = p

            start += best_gap

        return start + total_skill * mana[-1]
